"use client"

import { useEffect, useRef, type FC } from "react"
import Image, { type ImageLoader } from "next/image"

const passthroughLoader: ImageLoader = ({ src }) => src

export interface iCardItem {
  title: string
  description: string
  tag: string
  src: string
  link: string
  color: string
  textColor: string
}

interface iCardProps extends Omit<iCardItem, "src" | "link" | "tag"> {
  src: string
}

const Card: FC<iCardProps> = ({ title, description, color, textColor, src }) => (
  <div className="sticky top-0 flex h-screen items-center justify-center px-4 md:p-0">
    <div className="relative mx-auto flex aspect-[3/4] w-[min(80vw,360px)] flex-col items-center justify-center px-3 pb-4 pt-3 shadow-md" style={{ backgroundColor: color }}>
      {title && <span className="relative z-10 mt-5 text-5xl font-black tracking-tight md:text-7xl" style={{ color: textColor }}>{title}</span>}
      {description && <div className="relative z-10 mt-2 text-center text-lg font-medium lowercase tracking-wide md:text-2xl" style={{ lineHeight: 1.4, color: textColor }}>{description}</div>}
      <div className="absolute inset-0 z-0">
        <Image loader={passthroughLoader} className="object-cover" src={src} alt="" fill unoptimized sizes="(max-width: 768px) 100vw, 600px" />
      </div>
    </div>
  </div>
)

export function CardsParallax({ items }: { items: iCardItem[] }) {
  const sectionRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    const main = sectionRef.current?.closest("main")
    if (!main) return
    const previousOverflow = main.style.overflow
    main.style.overflow = "clip"
    return () => { main.style.overflow = previousOverflow }
  }, [])

  return <div ref={sectionRef} className="min-h-screen">{items.map((item, i) => <Card key={`p_${i}`} {...item} />)}</div>
}

const cardItems: iCardItem[] = [
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
  { title: "", description: "", tag: "", src: "data:image/svg+xml;base64,", link: "#", color: "white", textColor: "black" },
]

export default function AboutSection() {
  return <CardsParallax items={cardItems} />
}
